test("world generation keeps fixed feature counts per level", () => {
  const world = buildDungeonWorld(DEFAULT_GAME_CONFIG);

  for (let depth = DEFAULT_GAME_CONFIG.totalLevels; depth >= 1; depth -= 1) {
